### Request Inspector Service

```csharp
// Services/RequestInspectorService.cs
public class RequestInspectorService : IRequestInspectorService
{
    private readonly List<SqlInjectionSignature> _sqlSignatures;
    private readonly ILogger<RequestInspectorService> _logger;

    public RequestInspectorService(ILogger<RequestInspectorService> logger)
    {
        _logger = logger;
        InitializeSqlSignatures();
    }

    private void InitializeSqlSignatures()
    {
        _sqlSignatures = new List<SqlInjectionSignature>
        {
            new SqlInjectionSignature
            {
                Pattern = @"(?:'|--|\b(?:SELECT|INSERT|UPDATE|DELETE|DROP|UNION|EXEC|EXECUTE)\b|\b(?:OR|AND)\s+1=1)",
                Severity = "High",
                Description = "Classic SQL injection attempt",
                IsBlock = true
            },
            new SqlInjectionSignature
            {
                Pattern = @"\b(?:LOAD_FILE|INTO\s+OUTFILE|OUTER\s+JOIN|GROUP\s+CONCAT|HAVING\s+1=1)\b",
                Severity = "High",
                Description = "Advanced SQL injection technique",
                IsBlock = true
            },
            new SqlInjectionSignature
            {
                Pattern = @"\b(?:xp_|sp_|sys_)\b",
                Severity = "Medium",
                Description = "SQL Server stored procedure injection attempt",
                IsBlock = true
            }
        };
    }

    public bool InspectRequest(RequestMetadata metadata)
    {
        var inspectionResults = new List<InspectionResult>();

        // Check headers
        inspectionResults.AddRange(CheckHeaders(metadata.Headers));

        // Check query string
        inspectionResults.AddRange(CheckQueryString(metadata.QueryString));

        // Check body
        inspectionResults.AddRange(CheckBody(metadata.Body));

        // Log results
        foreach (var result in inspectionResults)
        {
            _logger.LogWarning($"SQL Injection Attempt Detected: {result.Message}");
        }

        // Return true if any high severity block was found
        return inspectionResults.Any(r => r.Severity == "High" && r.IsBlock);
    }

    private List<InspectionResult> CheckHeaders(Dictionary<string, string> headers)
    {
        var results = new List<InspectionResult>();

        foreach (var header in headers)
        {
            foreach (var signature in _sqlSignatures)
            {
                if (Regex.IsMatch(header.Value, signature.Pattern, RegexOptions.IgnoreCase))
                {
                    results.Add(new InspectionResult
                    {
                        Source = $"Header: {header.Key}",
                        Message = signature.Description,
                        Severity = signature.Severity,
                        IsBlock = signature.IsBlock
                    });
                }
            }
        }

        return results;
    }

    private List<InspectionResult> CheckQueryString(string queryString)
    {
        var results = new List<InspectionResult>();

        if (!string.IsNullOrEmpty(queryString))
        {
            foreach (var signature in _sqlSignatures)
            {
                if (Regex.IsMatch(queryString, signature.Pattern, RegexOptions.IgnoreCase))
                {
                    results.Add(new InspectionResult
                    {
                        Source = "Query String",
                        Message = signature.Description,
                        Severity = signature.Severity,
                        IsBlock = signature.IsBlock
                    });
                }
            }
        }

        return results;
    }

    private List<InspectionResult> CheckBody(string body)
    {
        var results = new List<InspectionResult>();

        if (!string.IsNullOrEmpty(body))
        {
            foreach (var signature in _sqlSignatures)
            {
                if (Regex.IsMatch(body, signature.Pattern, RegexOptions.IgnoreCase))
                {
                    results.Add(new InspectionResult
                    {
                        Source = "Request Body",
                        Message = signature.Description,
                        Severity = signature.Severity,
                        IsBlock = signature.IsBlock
                    });
                }
            }
        }

        return results;
    }
}

public interface IRequestInspectorService
{
    bool InspectRequest(RequestMetadata metadata);
}

public class InspectionResult
{
    public string Source { get; set; }
    public string Message { get; set; }
    public string Severity { get; set; }
    public bool IsBlock { get; set; }
}
```

### Rate Limiting and Reputation Engine

```csharp
// Services/RateLimiterService.cs
public class RateLimiterService : IRateLimiterService
{
    private readonly IReputationEngineService _reputationEngine;
    private readonly IRequestLogRepository _requestLogRepository;
    private readonly ILogger<RateLimiterService> _logger;
    private readonly TimeSpan _slidingWindowDuration;
    private readonly int _maxRequests;

    public RateLimiterService(
        IReputationEngineService reputationEngine,
        IRequestLogRepository requestLogRepository,
        IOptions<RateLimitSettings> settings,
        ILogger<RateLimiterService> logger)
    {
        _reputationEngine = reputationEngine;
        _requestLogRepository = requestLogRepository;
        _logger = logger;
        _slidingWindowDuration = settings.Value.SlidingWindowDuration;
        _maxRequests = settings.Value.MaxRequests;
    }

    public async Task<bool> CheckRateLimitAsync(string clientIp)
    {
        // Check reputation first
        if (_reputationEngine.IsBlocked(clientIp))
        {
            _logger.LogWarning($"Rate limit check skipped for blocked IP: {clientIp}");
            return true;
        }

        // Get request count in sliding window
        var requestCount = await _requestLogRepository.GetRequestCountInWindowAsync(
            clientIp,
            DateTime.UtcNow - _slidingWindowDuration,
            DateTime.UtcNow);

        if (requestCount >= _maxRequests)
        {
            _logger.LogWarning($"Rate limit exceeded for IP: {clientIp}. Requests: {requestCount}");
            return true;
        }

        return false;
    }

    public async Task LogRequestAsync(RequestMetadata metadata)
    {
        await _requestLogRepository.LogRequestAsync(metadata);
    }
}

public interface IRateLimiterService
{
    Task<bool> CheckRateLimitAsync(string clientIp);
    Task LogRequestAsync(RequestMetadata metadata);
}

// ReputationEngineService.cs
public class ReputationEngineService : IReputationEngineService
{
    private readonly IBlockedIPRepository _blockedIPRepository;
    private readonly ILogger<ReputationEngineService> _logger;

    public ReputationEngineService(
        IBlockedIPRepository blockedIPRepository,
        ILogger<ReputationEngineService> logger)
    {
        _blockedIPRepository = blockedIPRepository;
        _logger = logger;
    }

    public bool IsBlocked(string ip)
    {
        return _blockedIPRepository.IsBlocked(ip);
    }

    public async Task BlockIPAsync(string ip, string reason)
    {
        await _blockedIPRepository.BlockIPAsync(ip, reason);
        _logger.LogInformation($"IP {ip} blocked due to: {reason}");
    }

    public async Task UnblockIPAsync(string ip)
    {
        await _blockedIPRepository.UnblockIPAsync(ip);
        _logger.LogInformation($"IP {ip} unblocked");
    }
}

public interface IReputationEngineService
{
    bool IsBlocked(string ip);
    Task BlockIPAsync(string ip, string reason);
    Task UnblockIPAsync(string ip);
}
