### Incident Response System

```csharp
// Services/IncidentResponseService.cs
public class IncidentResponseService : IIncidentResponseService
{
    private readonly IRequestLogRepository _requestLogRepository;
    private readonly IReputationEngineService _reputationEngine;
    private readonly ILogger<IncidentResponseService> _logger;

    public IncidentResponseService(
        IRequestLogRepository requestLogRepository,
        IReputationEngineService reputationEngine,
        ILogger<IncidentResponseService> logger)
    {
        _requestLogRepository = requestLogRepository;
        _reputationEngine = reputationEngine;
        _logger = logger;
    }

    public async Task HandleIncidentAsync(RequestMetadata metadata, string incidentType)
    {
        // Log the incident
        await _requestLogRepository.LogIncidentAsync(metadata, incidentType);

        // Determine response based on incident type
        switch (incidentType)
        {
            case "sql_injection":
                await HandleSqlInjectionIncidentAsync(metadata);
                break;
            case "rate_limit":
                await HandleRateLimitIncidentAsync(metadata);
                break;
            default:
                _logger.LogWarning($"Unknown incident type: {incidentType}");
                break;
        }
    }

    private async Task HandleSqlInjectionIncidentAsync(RequestMetadata metadata)
    {
        // Check if IP is already blocked
        if (!_reputationEngine.IsBlocked(metadata.ClientIp))
        {
            await _reputationEngine.BlockIPAsync(
                metadata.ClientIp,
                $"SQL Injection Attempt: {metadata.Path}");

            _logger.LogError($"SQL Injection blocked for IP: {metadata.ClientIp}");
        }
    }

    private async Task HandleRateLimitIncidentAsync(RequestMetadata metadata)
    {
        // For rate limiting, we might want to temporarily block
        // or just log without blocking
        await _reputationEngine.BlockIPAsync(
            metadata.ClientIp,
            $"Rate Limit Exceeded: {metadata.RequestTime}");

        _logger.LogWarning($"Rate limit incident handled for IP: {metadata.ClientIp}");
    }
}

public interface IIncidentResponseService
{
    Task HandleIncidentAsync(RequestMetadata metadata, string incidentType);
}
```

### WAF Middleware

```csharp
// WafMiddleware.cs
public class WafMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IRequestInspectorService _requestInspector;
    private readonly IRateLimiterService _rateLimiter;
    private readonly IIncidentResponseService _incidentResponse;
    private readonly ILogger<WafMiddleware> _logger;

    public WafMiddleware(
        RequestDelegate next,
        IRequestInspectorService requestInspector,
        IRateLimiterService rateLimiter,
        IIncidentResponseService incidentResponse,
        ILogger<WafMiddleware> logger)
    {
        _next = next;
        _requestInspector = requestInspector;
        _rateLimiter = rateLimiter;
        _incidentResponse = incidentResponse;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            // Parse request metadata
            var metadata = ParseRequest(context);

            // Check rate limiting
            if (await _rateLimiter.CheckRateLimitAsync(metadata.ClientIp))
            {
                _logger.LogWarning($"Rate limit exceeded for IP: {metadata.ClientIp}");
                context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
                await context.Response.WriteAsync("Rate limit exceeded");
                return;
            }

            // Check for SQL injection
            if (_requestInspector.InspectRequest(metadata))
            {
                await _incidentResponse.HandleIncidentAsync(metadata, "sql_injection");
                context.Response.StatusCode = StatusCodes.Status403Forbidden;
                await context.Response.WriteAsync("SQL injection attempt detected");
                return;
            }

            // Log the request
            await _rateLimiter.LogRequestAsync(metadata);

            // Continue to the next middleware
            await _next(context);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "WAF middleware error");
            context.Response.StatusCode = StatusCodes.Status500InternalServerError;
            await context.Response.WriteAsync("WAF error occurred");
        }
    }

    private RequestMetadata ParseRequest(HttpContext context)
    {
        return new RequestMetadata
        {
            ClientIp = context.Connection.RemoteIpAddress?.ToString() ?? "unknown",
            UserAgent = context.Request.Headers.UserAgent.ToString(),
            RequestTime = DateTime.UtcNow,
            Method = context.Request.Method,
            Path = context.Request.Path.Value,
            Headers = context.Request.Headers.ToDictionary(
                h => h.Key,
                h => h.Value.ToString()),
            QueryString = context.Request.QueryString.Value,
            Body = context.Request.Body is not null
                ? await new StreamReader(context.Request.Body).ReadToEndAsync()
                : string.Empty
        };
    }
}
```

### Extension Methods

```csharp
// Extensions/ServiceCollectionExtensions.cs
public static class ServiceCollectionExtensions
{
    public static IServiceCollection AddWaf(this IServiceCollection services, Action<RateLimitSettings> configure)
    {
        // Configure settings
        services.Configure(configure);

        // Register services
        services.AddSingleton<IRequestInspectorService, RequestInspectorService>();
        services.AddSingleton<IRateLimiterService, RateLimiterService>();
        services.AddSingleton<IReputationEngineService, ReputationEngineService>();
        services.AddSingleton<IIncidentResponseService, IncidentResponseService>();

        // Register repositories (use in-memory for demo, replace with database in production)
        services.AddSingleton<IBlockedIPRepository, InMemoryBlockedIPRepository>();
        services.AddSingleton<IRequestLogRepository, InMemoryRequestLogRepository>();

        // Add logging
        services.AddLogging(configure => configure.AddConsole());

        return services;
    }

    public static IApplicationBuilder UseWaf(this IApplicationBuilder app)
    {
        return app.UseMiddleware<WafMiddleware>();
    }
}

// Settings class
public class RateLimitSettings
{
    public TimeSpan SlidingWindowDuration { get; set; } = TimeSpan.FromMinutes(1);
    public int MaxRequests { get; set; } = 100;
}
