### Infrastructure Repositories (In-Memory Implementation)

```csharp
// Infrastructure/Repositories/InMemoryBlockedIPRepository.cs
public class InMemoryBlockedIPRepository : IBlockedIPRepository
{
    private readonly ConcurrentDictionary<string, BlockedIP> _blockedIPs = new();
    private readonly object _lock = new();

    public bool IsBlocked(string ip)
    {
        return _blockedIPs.ContainsKey(ip);
    }

    public async Task BlockIPAsync(string ip, string reason)
    {
        lock (_lock)
        {
            _blockedIPs.TryAdd(ip, new BlockedIP
            {
                Ip = ip,
                BlockedAt = DateTime.UtcNow,
                Reason = reason
            });
        }
    }

    public async Task UnblockIPAsync(string ip)
    {
        lock (_lock)
        {
            _blockedIPs.TryRemove(ip, out _);
        }
    }
}

// Infrastructure/Repositories/InMemoryRequestLogRepository.cs
public class InMemoryRequestLogRepository : IRequestLogRepository
{
    private readonly ConcurrentQueue<RequestLog> _requestLogs = new();
    private readonly object _lock = new();

    public async Task LogRequestAsync(RequestMetadata metadata)
    {
        lock (_lock)
        {
            _requestLogs.Enqueue(new RequestLog
            {
                ClientIp = metadata.ClientIp,
                RequestTime = DateTime.UtcNow,
                IsBlocked = metadata.IsBlocked,
                BlockReason = metadata.BlockReason
            });
        }
    }

    public async Task<int> GetRequestCountInWindowAsync(string ip, DateTime start, DateTime end)
    {
        lock (_lock)
        {
            return _requestLogs.Count(log =>
                log.ClientIp == ip &&
                log.RequestTime >= start &&
                log.RequestTime <= end);
        }
    }

    public async Task LogIncidentAsync(RequestMetadata metadata, string incidentType)
    {
        lock (_lock)
        {
            _requestLogs.Enqueue(new RequestLog
            {
                ClientIp = metadata.ClientIp,
                RequestTime = DateTime.UtcNow,
                IsBlocked = true,
                BlockReason = $"Incident: {incidentType} - {metadata.Path}"
            });
        }
    }
}
